import { useEffect, useRef } from "react";
import { CloseIcon } from "./Icons";
import { useApp } from "../../context/AppContext";
import styles from "./StreamPlayer.module.css";

export default function StreamPlayer({ movie, onClose }) {
  const { addToContinueWatching } = useApp();
  const overlayRef = useRef(null);

  // Add to continue watching when player opens
  useEffect(() => {
    if (movie) {
      addToContinueWatching({
        ...movie,
        subtitle: "Continue watching",
        progress: 5,
      });
    }
    // Prevent body scroll while player is open
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = ""; };
  }, [movie]);

  // Close on Escape
  useEffect(() => {
    const h = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  }, [onClose]);

  if (!movie) return null;

  const tmdbId   = movie.id;
  const streamUrl = `https://vidsrc.to/embed/movie/${tmdbId}`;
  const title    = movie.title || movie.name;

  return (
    <div className={styles.overlay} ref={overlayRef}>
      <div className={styles.playerWrap}>
        {/* Header bar */}
        <div className={styles.header}>
          <span className={styles.nowPlaying}>▶ Now Playing</span>
          <h2 className={styles.title}>{title}</h2>
          <button className={styles.closeBtn} onClick={onClose} aria-label="Close player">
            <CloseIcon size={18} />
          </button>
        </div>

        {/* iFrame embed */}
        <div className={styles.frameWrap}>
          <iframe
            src={streamUrl}
            className={styles.frame}
            allowFullScreen
            allow="autoplay; fullscreen; encrypted-media"
            referrerPolicy="no-referrer"
            title={title}
            sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-presentation"
          />
        </div>

        {/* Footer note */}
        <div className={styles.footer}>
          <span className={styles.footerNote}>
            Streaming via vidsrc.to · Press Esc to close
          </span>
        </div>
      </div>
    </div>
  );
}
